mapper.update:
UPDATE tbl_baby_vaccination
SET completed = #{vaccination.completed},
completed_date = #{vaccination.completedDate},
hospital_name = #{vaccination.hospitalName}
WHERE vaccination_no = #{vaccination.vaccinationNo}
AND baby_no IN (SELECT baby_no FROM tbl_baby_info WHERE email = #{email})

mapper.delete:
DELETE FROM tbl_baby_vaccination
WHERE vaccination_no = #{vaccinationNo}
AND baby_no IN (SELECT baby_no FROM tbl_baby_info WHERE email = #{email})
